import assert from 'node:assert/strict';import{createRequire}from'node:module';import{resolve}from'node:path';import{pathToFileURL}from'node:url';import{mkdir,writeFile}from'node:fs/promises';
const require=createRequire(import.meta.url),{chromium}=require('C:/Users/genki/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright-core');const evidence=resolve('../../outputs/verification-v35-handedness-diagnosis-v1');await mkdir(evidence);
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
try{
 const page=await browser.newPage({viewport:{width:1200,height:860}});await page.goto(pathToFileURL(resolve('../../outputs/ばせぼーるlv34_TBD_vs_LAD_UI復元版.html')).href);await page.evaluate(()=>document.fonts.ready);
 const result=await page.evaluate(()=>{
  const data=JSON.parse(document.getElementById('match-data').textContent),measured=JSON.parse(document.getElementById('v33-measured-bats').textContent),roles=['P','C','1B','2B','3B','SS','LF','CF','RF'];
  const teams=[0,1].map(team=>({id:data.teams[team],name:data.teamNames[team],battingOrder:Array.from({length:9},(_,i)=>team+'-b'+i),pitcherId:team+'-p0',defense:Object.fromEntries(roles.map(role=>[role,role==='P'?team+'-p0':team+'-b'+data.defenseMap[team][role]]))}));
  window.handComparisons={};const evidence=[];
  for(const side of ['L','R']){
   const players=Object.values(data.players).map(p=>({playerId:p.id,name:p.name,heightMeters:p.height,bats:p.id==='0-b0'?side:p.hand}));
   const host=window.KneekuraNativeMatchCore.createLiveBaseballMatchV1({seed:1174965123,innings:9,teams,players,park:{fenceRadiusMeters:110,fenceHeightMeters:3},measuredClips:measured.clips});
   const record=host.issuePitch({managedTeam:0,batting:'balanced',pitchType:'auto',location:'auto'});
   const frames=record.frames.filter(f=>f.phase==='pitch'&&f.bat),frame=frames.at(-1),batter={...data.players[record.batterPlayerId],hand:side};
   const actors=frame.actors.map(a=>({id:a.playerId===record.batterPlayerId?'BAT':roles.includes(a.role)?a.role:'RUN:'+a.playerId,sourcePlayerId:a.playerId,role:a.role,position:a.position,running:false,walking:false,player:{...data.players[a.playerId],hand:a.playerId===record.batterPlayerId?side:a.role==='P'?data.players[a.playerId].throws:data.players[a.playerId].hand}}));
   const first=record.frames[0],world={liveObservation:true,livePark:host.inspect().fenceGeometry,liveBattedObservation:false,tick:frame.tick,localTick:28+(frame.tick-first.tick)/55000,batter,pitcher:data.players[record.pitcherPlayerId],actors,ball:frame.ball?.visible?{...frame.ball,sourceObservation:true,ballKind:'pitch'}:null,bat:{...frame.bat,sourceObservation:true},p:{contactLocal:null,catchLocal:null,swing:true,outcome:null,actors:[]},batFrame:0,pitchFrame:0,fair:false,fairKnown:frame.fairKnown,custody:frame.possessedBy,ballKind:'pitch',phase:frame.phase,history:[]};
   window.handComparisons[side]={world,frame,record};
   const rendered=window.matchPreview.liveDrawWorld(world,{camera:'mound',appearance:'retro',labels:true,zone:true,zoom:1,history:false});
   const axis={x:frame.bat.tip.x-frame.bat.grip.x,y:frame.bat.tip.y-frame.bat.grip.y,z:frame.bat.tip.z-frame.bat.grip.z};
   const last=frame.bat,atContact=record.play.contactMoment?.ball.position;
   evidence.push({side,sourceDiagnosticsHand:record.play.diagnostics.battingSide,batterAnchor:actors.find(a=>a.id==='BAT').position,axis,grip:last.grip,tip:last.tip,contact:atContact,
    renderedBatterRig:rendered.batterRig,camera:rendered.camera,cameraEye:rendered.cameraEye,batDisplayMode:rendered.batDisplayMode,
    measuredClips:measured.clips.filter(c=>c.side===side).map(c=>({id:c.id,side:c.side})),actualContact:!!record.play.contactMoment,fixture:'same original seed/height/parameters; only declared batting side differs'});
  }
  return evidence;
 });
 for(const r of result){assert.equal(r.sourceDiagnosticsHand,r.side);assert.equal(r.renderedBatterRig.hand,r.side);assert(r.side==='L'?r.axis.x>0:r.axis.x<0);assert(r.side==='L'?r.batterAnchor.x<0:r.batterAnchor.x>0);assert.equal(r.renderedBatterRig.includesIllustratedBat,false);}
 for(const side of ['L','R']){await page.evaluate(side=>window.matchPreview.liveDrawWorld(window.handComparisons[side].world,{camera:'mound',appearance:'retro',labels:true,zone:true,zoom:1,history:false}),side);await page.locator('.broadcast').screenshot({path:resolve(evidence,'mound-'+side+'.png')});}
 await writeFile(resolve(evidence,'handedness.json'),JSON.stringify({status:'PASS_NO_CLIP_SIDE_SWAP_REPRODUCED',comparisons:result},null,2)+'\n');console.log(JSON.stringify({status:'PASS_NO_CLIP_SIDE_SWAP_REPRODUCED',comparisons:result.map(r=>({side:r.side,axis:r.axis,bodySource:r.renderedBatterRig.sourceId,bodyHand:r.renderedBatterRig.hand,mirror:r.renderedBatterRig.viewMirrorX})),evidence},null,2));await page.close();
}finally{await browser.close();}
